// 1. Pega o valor correto da base de dados (agora a usar 'uf_municipio')
const valorOriginal = $json.uf_municipio || "";

// 2. Dicionário de Cidades (ID 1 a 86)
const mapaCidades = {
    // Estados (IDs 1 a 6)
    "bahia": 1, "piaui": 2, "ceara": 3, "minas gerais": 4, "maranhao": 5, "para": 6,

    // Cidades da Bahia
    "anage": 7, "angical": 8, "barra da estiva": 9, "barra do choca": 10, "brejolandia": 11,
    "cacule": 12, "caetanos": 13, "canapolis": 14, "candiba": 15, "carinhanha": 16,
    "cocos": 17, "dom basilio": 18, "erico cardoso": 19, "feira da mata": 20, "guanambi": 21,
    "ibicui": 22, "ibipitanga": 23, "itabuna": 24, "itagiba": 25, "itagimirim": 26,
    "itambe": 27, "itapebi": 28, "itororo": 29, "ituacu": 30, "iuiu": 31, "jaborandi": 32,
    "jussiape": 33, "macaubas": 34, "malhada": 35, "morpara": 36, "nova canaa": 37,
    "palmas de monte alto": 38, "palmeiras": 39, "paramirim": 40, "pindai": 41, "planalto": 42,
    "riacho de santana": 43, "ribeirao do largo": 44, "rio de contas": 45, "rio do pires": 46,
    "sao felix do coribe": 47, "sebastiao laranjeiras": 48, "serra dourada": 49,
    "tabocas do brejo velho": 50, "tanhacu": 51, "tanque novo": 52, "tremedal": 53,
    "una": 54, "urandi": 55, "vitoria da conquista": 56,

    // Cidades do Piauí
    "baixa grande do ribeiro": 57, "beneditinos": 58, "buriti dos montes": 59, "campo maior": 60,
    "canto do buriti": 61, "castelo do piaui": 62, "colonia do gurgueia": 63, "curimata": 64,
    "elesbao veloso": 66, "inhuma": 67, "isaias coelho": 68, "jaicos": 69, "juazeiro do piaui": 70,
    "lagoa alegre": 71, "marcolandia": 72, "matias olimpio": 73, "piracuruca": 74, "piripiri": 75,
    "santa filomena": 76, "sigefredo pacheco": 77, "valenca do piaui": 78,

    // Cidades do Ceará
    "brejo santo": 79, "itaicaba": 80, "senador de sa": 82,

    // Cidades de Minas Gerais
    "espinosa": 83, "pedra azul": 84,

    // Maranhão e Pará
    "colinas": 85, "ponta de pedras": 86
};

// 3. Função para extrair apenas a cidade e normalizar o texto
const extrairENormalizar = (textoOriginal) => {
    if (!textoOriginal) return "";

    // Passa para minúsculas e remove os acentos logo de cara
    let t = String(textoOriginal).toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "").trim();

    // Lista de UFs (sigla ou nome completo) que o script sabe reconhecer
    const UF = "ac|al|ap|am|ba|ce|df|es|go|ma|mt|ms|mg|pa|pb|pr|pe|pi|rj|rn|rs|ro|rr|sc|sp|se|to|bahia|piaui|ceara|minas gerais|maranhao|para";

    // Remove sufixo "Cidade - UF" ou "Cidade - Estado" no final.
    // Exige um separador de verdade (espaço, virgula ou hífen) antes da UF, pra nao apagar
    // o nome do estado quando o cliente digita SO o estado (ex: "Piauí" sozinho continua "piaui").
    const semSufixo = t.replace(new RegExp("[\\s,-]+\\b(" + UF + ")\\b$"), "").trim();
    if (semSufixo !== t && semSufixo) return semSufixo;

    // Remove prefixo "UF - Cidade" ou "Estado - Cidade" no inicio (ex: "Piauí - Piripiri").
    // Exige separador real depois da UF, pra nao apagar o nome do estado sozinho tambem.
    const semPrefixo = t.replace(new RegExp("^\\b(" + UF + ")\\b[\\s,-]+"), "").trim();
    if (semPrefixo !== t && semPrefixo) return semPrefixo;

    return t;
};

const cidadeLimpa = extrairENormalizar(valorOriginal);

// 4. Encontra o ID no mapa (se a cidade não existir na lista, retorna null)
const id_cidade_glpi = mapaCidades[cidadeLimpa] || null;

// 5. Retorno para o nó seguinte
return [{
    json: {
        texto_original: valorOriginal,
        cidade_processada: cidadeLimpa,
        id_municipio_glpi: id_cidade_glpi
    },
    pairedItem: { item: 0 }
}];

