parameters.jsCode:
// 1. Pega o horário atual forçando o fuso horário de Brasília
const agora = $now.setZone('America/Sao_Paulo');
const diaSemana = agora.weekday; // 1 = Segunda, 5 = Sexta, 6/7 = Fim de Semana
const hora = agora.hour;
const minuto = agora.minute;

let status = "fora"; // Por padrão, começa como fora de expediente

// 2. Valida se é dia de semana (Segunda a Sexta)
if (diaSemana >= 1 && diaSemana <= 5) {
    if (hora >= 8 && hora < 12) {
        status = "normal";
    } else if (hora >= 12 && hora < 13) {
        status = "almoco";
    } else if (hora >= 13 && hora < 18) {
        status = "normal";
    }
}

// 3. Retorna os dados mastigados para o fluxo e serve como diagnóstico
return {
    status_expediente: status,
    hora_no_servidor: hora,
    minuto_no_servidor: minuto,
    horario_formatado: agora.toFormat('HH:mm:ss'),
    dia_da_semana: diaSemana
};

