      },
      custom_attributes: {
        ...(initBody.custom_attributes || {}),
        protocolo: String(ticketId),
        link_chamado: `https://glpi.wmsaude.com.br/front/ticket.form.php?id=${ticketId}`
      }
    }
  }
}];

// Traduz o grupo GLPI do ticket antigo pra team_id Chatwoot, casando por nome
const gruposAssign = $('Busca grupo assign do ticket GLPI').all().filter(i => i.json.type === 2);
const gruposGlpi = $('Busca grupos GLPI (lista)').all();
const teamsChatwoot = $('Busca teams Chatwoot').all();

const normalizar = (t) => (t || '').trim().toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "");

const FALLBACK_TEAM_ID = 1097; // service desk

let resultado;

if (gruposAssign.length === 0) {
    resultado = { team_id: FALLBACK_TEAM_ID, sem_match: true };
} else {
    const groupId = gruposAssign[0].json.groups_id;
    const grupo = gruposGlpi.find(g => g.json.id === groupId);
    if (!grupo) {
        resultado = { team_id: FALLBACK_TEAM_ID, sem_match: true };
    } else {
        const nomeGrupoNormalizado = normalizar(grupo.json.name);
        const team = teamsChatwoot.find(t => normalizar(t.json.name) === nomeGrupoNormalizado);
        resultado = team
            ? { team_id: team.json.id, sem_match: false }
            : { team_id: FALLBACK_TEAM_ID, sem_match: true };
    }
}

return [{ json: resultado, pairedItem: { item: 0 } }];

