// 3. Normaliza texto: minusculo, remove acento, colapsa espacos
const normalizarBase = (texto) => {
    if (!texto) return "";
    let limpo = String(texto).toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "");
    limpo = limpo.replace(/\s+/g, " ").trim();
    return limpo;
};

// 4. Expande sinonimos de tipo (USF/UBS/CS/PS/PSF/UBSF) para um token canonico
// e remove conectores (de/da/do/dos/das), pra casar abreviacao com nome por extenso
const SINONIMOS = [
    ["unidade basica de saude da familia", "ubsf"],
    ["unidade de saude da familia", "usf"],
    ["unidade saude da familia", "usf"],
    ["unidade basica de saude", "ubs"],
    ["estrategia de saude da familia", "usf"],
    ["centro de saude", "cs"],
    ["posto de saude", "ps"],
    ["programa saude da familia", "psf"],
    ["u s f", "usf"],
];
const CONECTORES = new Set(["de", "da", "do", "dos", "das"]);
const TIPOS = new Set(["usf", "ubs", "ubsf", "cs", "ps", "psf", "eap", "eab", "pab"]);

const normalizarNucleo = (texto) => {
    let t = normalizarBase(texto);
    for (const [longa, curta] of SINONIMOS) {
        t = t.replace(new RegExp("\\b" + longa.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "\\b", "g"), curta);
    }
    const palavras = t.split(" ").filter(w => w && !CONECTORES.has(w));
    return palavras.join(" ").trim();
};

// 5. Remove tambem o token de tipo (usf/ubs/cs/ps/psf/ubsf) do inicio, ficando so
// com o "nome puro" da unidade (ex: "USF Ourives" -> "ourives")
const normalizarPuro = (texto) => {
    const nucleo = normalizarNucleo(texto);
    const palavras = nucleo.split(" ");
    if (palavras.length && TIPOS.has(palavras[0])) {
        palavras.shift();
    }
    return palavras.join(" ").trim();
};

// 6. Busca em 3 niveis:
//    a) nome completo exato (bate com o nome cadastrado no GLPI, com ou sem sigla)
//    b) nome puro, SEM o tipo - se so existir uma unidade com esse nome na base inteira,
//       ja usa ela direto (ex: cliente digita so "Ourives" ou "USF Ourives", ambos acham
//       a mesma unica unidade)
//    c) se o nome puro bater em mais de uma unidade (ex: existe "USF Sede" em varios
//       municipios, ou "UBS Santo Antonio" e "USF Santo Antonio"), usa o tipo que o
//       cliente digitou (USF/UBS/CS/PS/PSF) pra desempatar entre as opcoes
const unidadeExata = normalizarBase(valorOriginal);
const unidadePuro = normalizarPuro(valorOriginal);
const unidadeNucleo = normalizarNucleo(valorOriginal);

